"""Greedy paragraph-preserving text wrapping."""


def wrap(text, width):
    """Fill text greedily into lines of at most width characters (long words stay whole)."""
    if isinstance(width, bool) or not isinstance(width, int):
        raise ValueError(f"width must be an int, got {width!r}")
    if width < 1:
        raise ValueError("width must be >= 1")
    paragraphs, current = [], []
    for line in text.splitlines():
        if line.strip():
            current.append(line)
        elif current:
            paragraphs.append(current)
            current = []
    if current:
        paragraphs.append(current)
    out = []
    for lines in paragraphs:
        row = ""
        rows = []
        for word in " ".join(lines).split():
            if row and len(row) + 1 + len(word) <= width:
                row += " " + word
            else:
                if row:
                    rows.append(row)
                row = word
        rows.append(row)
        out.append("\n".join(rows))
    return "\n\n".join(out)
